#include <stdio.h>

union Value {
    int asInt;
    float asFloat;
};

struct TaggedValue {          // a 'tagged union' pattern: union + explicit type tag
    enum { IS_INT, IS_FLOAT } type;
    union Value value;
};

int main() {
    union Value v;
    v.asInt = 65;
    printf("%d\n", v.asInt);          // 65 — read back correctly, matching how it was written

    struct TaggedValue tv = { IS_INT, {.asInt = 42} };
    if (tv.type == IS_INT) {
        printf("%d\n", tv.value.asInt);   // safe: we know which member is valid
    }
    return 0;
}
